class Manacher:
    def __init__(self, input_string) -> None:
        self.input_string = input_string

    def palindromic_length(self, center, diff, string):
        if (center - diff == -1 or center + diff == len(string)
                or string[center - diff] != string[center + diff]):
            return 0
        return 1 + self.palindromic_length(center, diff + 1, string)

    def build_modified_string(self):
        new_input_string = ""
        for i in self.input_string[:len(self.input_string) - 1]:
            new_input_string += i + "|"
        new_input_string += self.input_string[-1]
        return new_input_string

    def extract_palindrome(self, modified_string, start, max_length):
        output_string = ""
        for i in modified_string[start - max_length:start + max_length + 1]:
            if i != "|":
                output_string += i
        return output_string

    def palindromic_string(self):
        max_length = 0
        start = 0

        modified_string = self.build_modified_string()

        for i in range(len(modified_string)):
            length = self.palindromic_length(i, 1, modified_string)

            if max_length < length:
                max_length = length
                start = i

        return self.extract_palindrome(modified_string, start, max_length)
